from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def read_root(x_token: str = Header()):
    return {"x_token": x_token}

@app.get("/underscore")
async def read_underscore(strange_header: str = Header(convert_underscores=False)):
    return {"strange_header": strange_header}

client = TestClient(app)

def test_header_hyphen():
    # Should work: x-token -> x_token
    response = client.get("/", headers={"x-token": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_token": "foo"}

def test_header_underscore_rejected():
    # Should NOT work: x_token -> x_token (when convert_underscores=True)
    # The issue says "Do not accept underscore headers when using convert_underscores=True"
    # This means if we send 'x_token', it should not be mapped to 'x_token'
    response = client.get("/", headers={"x_token": "foo"})
    assert response.status_code == 422

def test_header_underscore_accepted_explicitly():
    # Should work: strange_header -> strange_header (when convert_underscores=False)
    response = client.get("/underscore", headers={"strange_header": "bar"})
    assert response.status_code == 200
    assert response.json() == {"strange_header": "bar"}
